describe('Long-running task persistence', () => {
    beforeEach(() => {
        cy.visit('/task-page');
    });

    it('should persist the long-running task across page refreshes', () => {
        cy.get('#start-task-button').click();
        cy.get('#task-status').should('contain', 'Task in progress');

        // Simulate a delay for the task
        cy.wait(5000);

        cy.reload();

        cy.get('#task-status').should('contain', 'Task in progress');
    });

    it('should handle edge case when task is completed before refresh', () => {
        cy.get('#start-task-button').click();
        cy.get('#task-status').should('contain', 'Task in progress');

        // Simulate task completion
        cy.wait(5000);
        cy.get('#complete-task-button').click();

        cy.reload();

        cy.get('#task-status').should('contain', 'Task completed');
    });
});
